// Tema 6 · bloque 5 · págs. 42-51 del temario oficial · LO 4/2000, arts. 68 a 72 y disposiciones; Ley 12/2009, arts. 1 a 7 · IA estilo examen (6-ia-1401…)
const k = 'lo4', l = 'l12';
const Q = [
// pág. 42 · arts. 68.2 a 72
{k, a: 'art. 68.3', r: 'Coordinación de las Administraciones Públicas', e: 'Con carácter previo a la concesión de autorizaciones por arraigo, emitirán un informe sobre la integración social del extranjero cuyo domicilio habitual se encuentre en su territorio:',
 o: ['las Comunidades Autónomas o, en su caso, los Ayuntamientos.', 'las Delegaciones o Subdelegaciones del Gobierno de la provincia.', 'los Servicios Públicos de Empleo de la Comunidad Autónoma.', 'las Oficinas de Extranjeros o, en su caso, las Comisarías.'],
 t: 'Con carácter previo a la concesión de autorizaciones por arraigo, las Comunidades Autónomas o, en su caso, los Ayuntamientos, emitirán un informe sobre la integración social del extranjero cuyo domicilio habitual se encuentre en su territorio',
 p: 'El informe de integración para el arraigo es de las Comunidades Autónomas o, en su caso, de los Ayuntamientos.'},
{k, a: 'art. 68.3', r: 'Coordinación de las Administraciones Públicas', e: 'El informe sobre la integración social del extranjero previo a la concesión de autorizaciones por arraigo tendrá en cuenta, en todo caso: Señale la INCORRECTA.',
 o: ['la carencia de antecedentes penales en España y en su país de origen.', 'el periodo de permanencia.', 'los vínculos con familiares residentes en España.', 'los esfuerzos de integración a través del seguimiento de programas de inserción sociolaborales y culturales.'],
 t: 'En todo caso, el informe tendrá en cuenta el periodo de permanencia, la posibilidad de contar con vivienda y medios de vida, los vínculos con familiares residentes en España, y los esfuerzos de integración a través del seguimiento de programas de inserción sociolaborales y culturales',
 p: 'Los antecedentes penales no figuran entre los contenidos del informe de integración.', d: 'dificil'},
{k, a: 'art. 68.4', r: 'Coordinación de las Administraciones Públicas', e: 'Las Comunidades Autónomas que hayan asumido competencias en materia de seguridad ciudadana y orden público mediante la creación de una policía propia podrán aportar, en su caso, en los procedimientos de autorización de residencia o su renovación en los que se prevea la necesidad de informe gubernativo:',
 o: ['un informe sobre afectación al orden público, que se incorporará al expediente.', 'un informe vinculante sobre la concesión o denegación de la autorización solicitada.', 'un informe sobre antecedentes policiales en sustitución del estatal.', 'un informe de integración social, previo a la concesión del arraigo.'],
 t: 'podrán aportar, en su caso, un informe sobre afectación al orden público en todos los procedimientos de autorización de residencia o su renovación',
 p: 'Aportan un informe sobre afectación al orden público, que se incorpora al expediente junto al de las FFCCSE; no es vinculante.'},
{k, a: 'art. 71', r: 'Observatorio Español del Racismo y la Xenofobia', e: 'Se constituirá el Observatorio Español del Racismo y la Xenofobia, en materia de lucha contra el racismo y la xenofobia, con:',
 o: ['funciones de estudio y análisis, y con capacidad para elevar propuestas de actuación.', 'funciones de inspección y sanción, y con capacidad para incoar expedientes.', 'funciones de consulta, información y asesoramiento en materia de integración.', 'funciones de coordinación de las Administraciones Públicas en esta materia.'],
 t: 'Se constituirá el Observatorio Español del Racismo y la Xenofobia, con funciones de estudio y análisis, y con capacidad para elevar propuestas de actuación, en materia de lucha contra el racismo y la xenofobia',
 p: 'Estudio y análisis y propuestas; la consulta y asesoramiento son del Foro; la coordinación, de la Conferencia Sectorial.'},
{k, a: 'art. 72.1', r: 'Comisión Laboral Tripartita de Inmigración', e: 'La Comisión Laboral Tripartita de Inmigración es el órgano colegiado adscrito al Ministerio competente en materia de inmigración, del que forman parte:',
 o: ['las organizaciones sindicales y empresariales más representativas.', 'las Comunidades Autónomas y las asociaciones de inmigrantes.', 'la Administración General del Estado, las CCAA y los Ayuntamientos.', 'las organizaciones no gubernamentales y los agentes sociales.'],
 t: 'La Comisión Laboral Tripartita de Inmigración es el órgano colegiado adscrito al Ministerio competente en materia de inmigración, de la que forman parte las organizaciones sindicales y empresariales más representativas',
 p: 'Forman parte las organizaciones sindicales y empresariales más representativas.'},
{k, a: 'art. 70.1', r: 'El Foro para la Integración Social de los Inmigrantes', e: 'El Foro para la Integración Social de los Inmigrantes está constituido:',
 o: ['de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio.', 'de forma paritaria, por representantes de la Administración General del Estado y de las organizaciones sindicales y empresariales más representativas.', 'de forma tripartita, por representantes de la Administración General del Estado, de las Comunidades Autónomas y de los Ayuntamientos con mayor población inmigrante, designados por la Conferencia Sectorial de Inmigración.', 'por representantes de las asociaciones de inmigrantes y de las organizaciones no gubernamentales, designados por el Ministerio competente en materia de inmigración.'],
 t: 'El Foro para la Integración Social de los Inmigrantes, constituido de forma tripartita y equilibrada, por representantes de las Administraciones Públicas, de las asociaciones de inmigrantes y de otras organizaciones con interés e implantación en el ámbito migratorio',
 p: 'Tripartito y equilibrado: Administraciones, asociaciones de inmigrantes y otras organizaciones (incluidas las sindicales y empresariales).', d: 'dificil'},
// pág. 43 · disposiciones adicionales primera a tercera
{k, a: 'disp. adic. 1.ª.1', r: 'Plazo máximo para resolución de expedientes', e: 'El plazo general máximo para notificar las resoluciones de las solicitudes de autorizaciones es de tres meses, sin perjuicio del plazo máximo establecido por la normativa comunitaria en relación con procedimientos de solicitud de visado de tránsito o estancia, que es de:',
 o: ['15 días naturales.', '15 días hábiles.', '10 días naturales.', '30 días naturales.'],
 t: 'sin perjuicio del plazo máximo de 15 días naturales establecido por la normativa comunitaria en relación con procedimientos de solicitud de visado de tránsito o estancia',
 p: 'Quince días naturales para los visados de tránsito o estancia.', d: 'dificil'},
{k, a: 'disp. adic. 1.ª.1', r: 'Plazo máximo para resolución de expedientes', e: 'Transcurrido el plazo general para notificar las resoluciones de las solicitudes de autorizaciones, salvo lo dispuesto para prórrogas y renovaciones, éstas:',
 o: ['podrán entenderse desestimadas.', 'se entenderán estimadas en todo caso.', 'se entenderán caducadas de oficio.', 'deberán resolverse en otros tres meses.'],
 t: 'Transcurrido el plazo para notificar las resoluciones de las solicitudes, salvo lo dispuesto en el apartado siguiente, éstas podrán entenderse desestimadas',
 p: 'Regla general: silencio desestimatorio.'},
{k, a: 'disp. adic. 1.ª.2', r: 'Plazo máximo para resolución de expedientes', e: 'Las solicitudes de prórroga de la autorización de residencia, la renovación de la autorización de trabajo y las de autorización de residencia de larga duración se resolverán y notificarán en el plazo máximo de tres meses. Transcurrido dicho plazo sin respuesta expresa:',
 o: ['se entenderá que la prórroga o renovación han sido concedidas.', 'se entenderá que la prórroga o renovación han sido denegadas.', 'se entenderá caducado el procedimiento de renovación.', 'deberá reiterarse la solicitud ante el mismo órgano.'],
 t: 'Transcurrido dicho plazo sin que la Administración haya dado respuesta expresa, se entenderá que la prórroga o renovación han sido concedidas',
 p: 'En prórrogas, renovaciones y larga duración el silencio es positivo.'},
{k, a: 'disp. adic. 1.ª.3', r: 'Plazo máximo para resolución de expedientes', e: 'Las solicitudes de modificación de la limitación territorial o de ocupación de las autorizaciones iniciales de residencia y trabajo se resolverán y notificarán por la administración autonómica o estatal competente en el plazo máximo de:',
 o: ['un mes, entendiéndose concedida la solicitud si no hay respuesta expresa.', 'tres meses, entendiéndose concedida la solicitud si no hay respuesta expresa.', 'un mes, entendiéndose desestimada la solicitud si no hay respuesta expresa.', 'quince días, entendiéndose concedida la solicitud si no hay respuesta expresa.'],
 t: 'Las solicitudes de modificación de la limitación territorial o de ocupación de las autorizaciones iniciales de residencia y trabajo se resolverán y notificarán por la administración autonómica o estatal competente en el plazo máximo de un mes',
 p: 'Un mes con silencio positivo.', d: 'dificil'},
{k, a: 'disp. adic. 2.ª', r: 'Subcomisiones de Cooperación', e: 'En atención a la situación geográfica del archipiélago canario, a la fragilidad de su territorio insular y a su lejanía con el continente europeo, se constituirá una subcomisión que conocerá de las cuestiones que afecten directamente a Canarias en materia de residencia y trabajo de extranjeros:',
 o: ['en el seno de la Comisión Bilateral de Cooperación Canarias-Estado.', 'en el seno de la Conferencia Sectorial de Inmigración.', 'en el seno de la Comisión Laboral Tripartita de Inmigración.', 'en el seno de la Delegación del Gobierno en Canarias.'],
 t: 'en el seno de la Comisión Bilateral de Cooperación Canarias-Estado se constituirá una subcomisión que conocerá de las cuestiones que afecten directamente a Canarias en materia de residencia y trabajo de extranjeros',
 p: 'La subcomisión se constituye en la Comisión Bilateral de Cooperación Canarias-Estado.'},
{k, a: 'disp. adic. 3.ª.1', r: 'Lugares de presentación de las solicitudes y exigencia de comparecencia personal', e: 'Cuando el sujeto legitimado se encuentre en territorio español habrá de presentar personalmente las solicitudes relativas a las autorizaciones de residencia y de trabajo en los registros de los órganos competentes para su tramitación. En los procedimientos en los que el sujeto legitimado fuese un empleador:',
 o: ['las solicitudes podrán ser presentadas por éste, o por quien válidamente ostente la representación legal empresarial.', 'las solicitudes deberán ser presentadas personalmente por el trabajador extranjero ante la Oficina de Extranjeros.', 'las solicitudes deberán presentarse en la misión diplomática u oficina consular del país de origen del trabajador.', 'las solicitudes solo podrán presentarse por medios electrónicos a través de la aplicación informática común.'],
 t: 'Igualmente, en los procedimientos en los que el sujeto legitimado fuese un empleador, las solicitudes podrán ser presentadas por éste, o por quien válidamente ostente la representación legal empresarial',
 p: 'El empleador o quien ostente válidamente la representación legal empresarial.'},
// pág. 44 · disposiciones adicionales tercera y cuarta
{k, a: 'disp. adic. 3.ª.2', r: 'Lugares de presentación de las solicitudes y exigencia de comparecencia personal', e: 'Cuando el sujeto legitimado se encuentre en territorio extranjero, la presentación de solicitudes de visado y su recogida se realizarán personalmente ante la misión diplomática u oficina consular en cuya demarcación aquél resida. Excepcionalmente, podrá acordarse que la solicitud pueda presentarse por representante debidamente acreditado cuando:',
 o: ['el interesado no resida en la población en que tenga su sede la misión u oficina y se acrediten razones que obstaculicen el desplazamiento.', 'el interesado sea menor de edad o persona con discapacidad que no pueda comparecer personalmente ante la misión diplomática u oficina consular.', 'la misión diplomática u oficina consular no disponga de personal suficiente para atender las solicitudes presentadas.', 'el interesado acredite haber presentado anteriormente otra solicitud de visado ante la misma misión u oficina consular.'],
 t: 'Excepcionalmente, cuando el interesado no resida en la población en que tenga su sede la misión diplomática u oficina consular y se acrediten razones que obstaculicen el desplazamiento, como la lejanía de la misión u oficina o dificultades de transporte que hagan el viaje especialmente gravoso, podrá acordarse que la solicitud de visado pueda presentarse por representante debidamente acreditado',
 p: 'La excepción se basa en no residir en la población sede y en razones que obstaculicen el desplazamiento.', d: 'dificil'},
{k, a: 'disp. adic. 3.ª.2', r: 'Lugares de presentación de las solicitudes y exigencia de comparecencia personal', e: 'En los supuestos de presentación de solicitudes y recogida de visado de estancia, tránsito y de residencia por reagrupación familiar de menores:',
 o: ['ambos trámites podrán realizarse mediante representante debidamente acreditado.', 'ambos trámites deberán realizarse personalmente por el reagrupante en España.', 'solo la recogida del visado podrá realizarse mediante representante acreditado.', 'ambos trámites deberán realizarse a través de un proveedor de servicios externo.'],
 t: 'en los supuestos de presentación de solicitudes y recogida de visado de estancia, tránsito y de residencia por reagrupación familiar de menores, ambos trámites podrán realizarse mediante representante debidamente acreditado',
 p: 'Ambos trámites caben por representante debidamente acreditado.'},
{k, a: 'disp. adic. 3.ª.3', r: 'Lugares de presentación de las solicitudes y exigencia de comparecencia personal', e: 'No se requerirá la comparecencia personal:',
 o: ['en los procedimientos de contratación colectiva de trabajadores, en los supuestos contemplados en un convenio o acuerdo internacional.', 'en los procedimientos de renovación de las autorizaciones de residencia temporal de los residentes legales que acrediten su esfuerzo de integración.', 'en los procedimientos de reagrupación familiar de los residentes de larga duración en España.', 'en los procedimientos de solicitud de visado de estudios para cursar estudios superiores en España.'],
 t: 'Asimismo, no se requerirá la comparecencia personal en los procedimientos de contratación colectiva de trabajadores, en los supuestos contemplados en un convenio o acuerdo internacional',
 p: 'Se exceptúa la contratación colectiva en los supuestos de un convenio o acuerdo internacional.'},
{k, a: 'disp. adic. 4.ª.1', r: 'Inadmisión a trámite de solicitudes', e: 'La autoridad competente para resolver inadmitirá a trámite las solicitudes relativas a los procedimientos regulados en esta ley, en los siguientes supuestos: Señale la INCORRECTA.',
 o: ['Cuando el solicitante haya sido sancionado por una infracción leve en el año anterior.', 'Cuando se trate de solicitudes manifiestamente carentes de fundamento.', 'Cuando dicha solicitud no sea realizada personalmente y dicha circunstancia sea exigida por ley.', 'Cuando se refieran a extranjeros que se encontrasen en España en situación irregular, salvo que puedan encontrarse en un supuesto de arraigo o circunstancias excepcionales.'],
 t: 'f) Cuando se trate de solicitudes manifiestamente carentes de fundamento',
 p: 'Una sanción leve previa no es causa de inadmisión.'},
{k, a: 'disp. adic. 4.ª.2', r: 'Inadmisión a trámite de solicitudes', e: 'En los procedimientos relativos a solicitudes de visado de tránsito o estancia, se inadmitirá a trámite la solicitud presentada:',
 o: ['fuera del plazo de los tres meses anteriores al comienzo del viaje.', 'fuera del plazo de los seis meses anteriores al comienzo del viaje.', 'con menos de quince días de antelación al comienzo del viaje.', 'fuera del plazo de un mes anterior al comienzo del viaje.'],
 t: 'a) Presentación de la solicitud fuera del plazo de los tres meses anteriores al comienzo del viaje',
 p: 'Dentro de los tres meses anteriores al comienzo del viaje.', d: 'dificil'},
{k, a: 'disp. adic. 4.ª.2.c)', r: 'Inadmisión a trámite de solicitudes', e: 'Se inadmitirá a trámite la solicitud de visado de tránsito o estancia cuando no se aporte documento de viaje válido al menos hasta tres meses después de la fecha prevista de salida del territorio de los Estados miembros; en el que figuren al menos dos páginas en blanco; y expedido dentro de los:',
 o: ['diez años anteriores a la presentación de la solicitud de visado.', 'cinco años anteriores a la presentación de la solicitud de visado.', 'diez años anteriores a la fecha prevista de entrada.', 'quince años anteriores a la presentación de la solicitud.'],
 t: 'y expedido dentro de los diez años anteriores a la presentación de la solicitud de visado',
 p: 'Tres meses de validez tras la salida, dos páginas en blanco y expedido en los diez años anteriores.', d: 'dificil'},
// pág. 45 · disposición adicional quinta
{k, a: 'disp. adic. 5.ª.2', r: 'Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos', e: 'Para la exclusiva finalidad de cumplimentar las actuaciones de los órganos de la Administración General del Estado competentes en materia de extranjería, facilitarán a aquéllos el acceso directo a los ficheros en los que obren datos que hayan de constar en dichos expedientes, sin que sea preciso el consentimiento de los interesados:',
 o: ['la Agencia Estatal de Administración Tributaria, la Tesorería General de la Seguridad Social y el Instituto Nacional de Estadística.', 'la Agencia Estatal de Administración Tributaria, el Servicio Público de Empleo Estatal y la Dirección General de Tráfico.', 'la Tesorería General de la Seguridad Social, el Registro Civil y el Instituto Nacional de Estadística.', 'el Instituto Nacional de Estadística, los Ayuntamientos y el Registro Central de Penados.'],
 t: 'la Agencia Estatal de Administración Tributaria, la Tesorería General de la Seguridad Social y el Instituto Nacional de Estadística, este último en lo relativo al Padrón Municipal de Habitantes, facilitarán a aquéllos el acceso directo a los ficheros',
 p: 'AEAT, TGSS e INE (este, en lo relativo al Padrón).'},
{k, a: 'disp. adic. 5.ª.3', r: 'Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos', e: 'La tramitación de los procedimientos en materia de extranjería se realizará sobre una aplicación informática común cuya implantación y coordinación respecto de los restantes Departamentos implicados corresponderá:',
 o: ['al Ministerio de Trabajo e Inmigración.', 'al Ministerio del Interior.', 'al Ministerio de Asuntos Exteriores y de Cooperación.', 'al Ministerio de Política Territorial.'],
 t: 'se realizará sobre una aplicación informática común cuya implantación y coordinación respecto de los restantes Departamentos implicados corresponderá al Ministerio de Trabajo e Inmigración',
 p: 'La aplicación común la coordina el Ministerio de Trabajo e Inmigración; el Registro central de extranjeros, el de Interior; los visados, Exteriores.'},
{k, a: 'disp. adic. 5.ª.3', r: 'Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos', e: 'De acuerdo con sus competencias en materia de orden público, seguridad pública y seguridad nacional, mantendrá un Registro central de extranjeros:',
 o: ['el Ministerio del Interior.', 'el Ministerio de Trabajo e Inmigración.', 'el Ministerio de Asuntos Exteriores.', 'el Instituto Nacional de Estadística.'],
 t: 'El Ministerio del Interior, de acuerdo con sus competencias en materia de orden público, seguridad pública y seguridad nacional, mantendrá un Registro central de extranjeros',
 p: 'El Registro central de extranjeros lo mantiene el Ministerio del Interior.'},
{k, a: 'disp. adic. 5.ª.3', r: 'Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos', e: 'En cumplimiento de lo establecido por la normativa comunitaria, la tramitación de procedimientos relativos a visados de tránsito y de estancia se realizará sobre la aplicación informática específicamente creada a los efectos, dependiente:',
 o: ['del Ministerio de Asuntos Exteriores y de Cooperación, interconectada con la aplicación informática común.', 'del Ministerio del Interior, interconectada con el Registro central de extranjeros.', 'del Ministerio de Trabajo e Inmigración, integrada en la aplicación informática común y en el Registro central de extranjeros.', 'de la Comisión Europea, a través del Sistema de Información de Visados.'],
 t: 'la tramitación de procedimientos relativos a visados de tránsito y de estancia se realizará sobre la aplicación informática específicamente creada a los efectos, dependiente del Ministerio de Asuntos Exteriores y de Cooperación, que estará interconectada con la aplicación informática común',
 p: 'Visados de tránsito y estancia: aplicación del Ministerio de Asuntos Exteriores, interconectada con la común.', d: 'dificil'},
{k, a: 'disp. adic. 5.ª.5', r: 'Acceso a la información, colaboración entre Administraciones públicas y gestión informática de los procedimientos', e: 'Aunará el conjunto de la información estadística disponible en materia de extranjería, inmigración, protección internacional y nacionalidad, con independencia de la Administración Pública, Departamento ministerial u Organismo responsable de su elaboración:',
 o: ['el Observatorio Permanente de la Inmigración.', 'el Observatorio Español del Racismo y la Xenofobia.', 'el Instituto Nacional de Estadística.', 'el Foro para la Integración Social de los Inmigrantes.'],
 t: 'El Observatorio Permanente de la Inmigración aunará el conjunto de la información estadística disponible en materia de extranjería, inmigración, protección internacional y nacionalidad',
 p: 'Es el Observatorio Permanente de la Inmigración (no el del Racismo y la Xenofobia).'},
// pág. 46 · disposiciones adicionales sexta a undécima.1
{k, a: 'disp. adic. 6.ª', r: 'Acuerdos de readmisión', e: 'En el caso de que el titular de la tarjeta azul de la U.E. concedida en España fuera objeto de una medida de repatriación en otro Estado miembro, por haberse extinguido la vigencia de la autorización originaria para permanecer en dicho Estado o por denegarse su solicitud para residir en él:',
 o: ['se le readmitirá sin necesidad de ninguna otra formalidad, incluyendo, en su caso, a los miembros de su familia previamente reagrupados.', 'se le readmitirá previa solicitud de visado de residencia, sin incluir a los miembros de su familia reagrupados.', 'no se le readmitirá si la tarjeta azul de la U.E. hubiera caducado durante su estancia en el otro Estado miembro, salvo acuerdo de readmisión.', 'se le readmitirá previa tramitación de un nuevo procedimiento de autorización de residencia y trabajo.'],
 t: 'se le readmitirá sin necesidad de ninguna otra formalidad, incluyendo, en su caso, a los miembros de su familia previamente reagrupados',
 p: 'Readmisión sin formalidades, incluida la familia previamente reagrupada.'},
{k, a: 'disp. adic. 7.ª', r: 'Delimitación del Espacio Schengen', e: 'A los efectos de lo dispuesto en esta ley, se entenderá por Espacio Schengen el conjunto de los territorios de los Estados a los que se apliquen plenamente las disposiciones relativas a la supresión de controles en las fronteras interiores y circulación de personas, previstas en:',
 o: ['el título II del Convenio para la aplicación del Acuerdo de Schengen, de 19 de junio de 1990.', 'el título I del Acuerdo de Schengen, de 14 de junio de 1985.', 'el Código de fronteras Schengen aprobado por el Reglamento del Parlamento Europeo y del Consejo.', 'el título II del Tratado de Funcionamiento de la Unión Europea.'],
 t: 'previstas en el título II del Convenio para la aplicación del Acuerdo de Schengen, de 19 de junio de 1990',
 p: 'Título II del Convenio de aplicación de 19 de junio de 1990.', d: 'dificil'},
{k, a: 'disp. adic. 8.ª', r: 'Ayudas al retorno voluntario', e: 'El Gobierno contemplará anualmente la financiación de programas de retorno voluntario de las personas que así lo soliciten y planteen proyectos que supongan su reasentamiento en la sociedad de la que partieron:',
 o: ['y siempre que los mismos sean de interés para aquella comunidad.', 'y siempre que acrediten la carencia de recursos económicos suficientes.', 'y siempre que hayan residido legalmente en España al menos dos años.', 'y siempre que se comprometan a no retornar a España durante cinco años.'],
 t: 'y planteen proyectos que supongan su reasentamiento en la sociedad de la que partieron y siempre que los mismos sean de interés para aquella comunidad',
 p: 'El requisito es que los proyectos sean de interés para aquella comunidad.'},
{k, a: 'disp. adic. 10.ª', r: 'Régimen especial de Ceuta y Melilla', e: 'Los extranjeros que sean detectados en la línea fronteriza de la demarcación territorial de Ceuta o Melilla mientras intentan superar los elementos de contención fronterizos para cruzar irregularmente la frontera:',
 o: ['podrán ser rechazados a fin de impedir su entrada ilegal en España, respetando la normativa internacional de derechos humanos y de protección internacional.', 'serán objeto de devolución sin necesidad de expediente de expulsión, previa identificación y comunicación al Juez de Instrucción del lugar en que se produzca.', 'podrán ser rechazados, salvo que manifiesten su voluntad de solicitar protección internacional en el mismo lugar del rechazo.', 'serán conducidos a las dependencias policiales para la incoación del correspondiente expediente de expulsión preferente.'],
 t: 'podrán ser rechazados a fin de impedir su entrada ilegal en España',
 p: 'Pueden ser rechazados, respetando la normativa de derechos humanos y protección internacional; las solicitudes se formalizan en los pasos fronterizos habilitados.'},
{k, a: 'disp. adic. 11.ª.1', r: 'Capacidad ordinaria de los sistemas para la adecuada protección y tutela de las personas menores de edad extranjeras no acompañadas', e: 'En defecto de acuerdo unánime de la Conferencia Sectorial, la capacidad ordinaria del sistema de protección y tutela de menores se obtendrá de dividir la población total de cada comunidad autónoma a 31 de diciembre del año anterior por el cociente resultante de dividir la población total de España a esa fecha entre:',
 o: ['el número máximo de personas menores de edad extranjeras no acompañadas atendidas por el conjunto del sistema de protección español.', 'el número medio de plazas de acogida existentes en el conjunto del Estado por cada 100.000 habitantes en el año anterior.', 'el número de personas menores de edad extranjeras no acompañadas inscritas en el Registro a 31 de marzo del año anterior.', 'el número total de comunidades y ciudades autónomas que integran la Conferencia Sectorial de Infancia y Adolescencia.'],
 t: 'por el cociente resultante de dividir la población total de España a 31 de diciembre del año anterior entre el número máximo de personas menores de edad extranjeras no acompañadas atendidas por el conjunto del sistema de protección español',
 p: 'El divisor es el número máximo de menores atendidos por el conjunto del sistema español.', d: 'dificil'},
// pág. 47 · disposición adicional undécima
{k, a: 'disp. adic. 11.ª.2', r: 'Capacidad ordinaria de los sistemas para la adecuada protección y tutela de las personas menores de edad extranjeras no acompañadas', e: 'La capacidad ordinaria del sistema de protección y tutela de personas menores de edad extranjeras no acompañadas se aprobará anualmente:',
 o: ['mediante real decreto, previa información a la Conferencia Sectorial de Infancia y Adolescencia.', 'mediante orden ministerial, previo acuerdo unánime de la Conferencia Sectorial de Infancia y Adolescencia.', 'por la Conferencia Sectorial de Infancia y Adolescencia, previo informe del Ministerio de Juventud e Infancia.', 'mediante ley, previa propuesta del Gobierno y acuerdo de la Conferencia Sectorial.'],
 t: 'Mediante real decreto, previa información a la Conferencia Sectorial de Infancia y Adolescencia, se aprobará anualmente cuál es la capacidad ordinaria del sistema de protección y tutela de personas menores de edad extranjeras no acompañadas',
 p: 'Real decreto, previa información a la Conferencia Sectorial.'},
{k, a: 'disp. adic. 11.ª.3', r: 'Capacidad ordinaria de los sistemas para la adecuada protección y tutela de las personas menores de edad extranjeras no acompañadas', e: 'Las ciudades y comunidades autónomas deberán remitir a la persona titular de la Presidencia de la Conferencia Sectorial de Infancia y Adolescencia certificación del número máximo de personas menores de edad extranjeras no acompañadas atendidas por su sistema de protección en el año anterior:',
 o: ['antes del 15 de enero de cada año.', 'antes del 31 de enero de cada año.', 'antes del 31 de marzo de cada año.', 'antes del 15 de febrero de cada año.'],
 t: 'antes del 15 de enero de cada año certificación del titular de la Consejería competente del número máximo de personas menores de edad extranjeras no acompañadas atendidas',
 p: 'Antes del 15 de enero; el 31 de marzo de 2025 era la fecha de los datos iniciales.', d: 'dificil'},
{k, a: 'disp. adic. 11.ª.4', r: 'Capacidad ordinaria de los sistemas para la adecuada protección y tutela de las personas menores de edad extranjeras no acompañadas', e: 'Para dotar en el año 2025 el Fondo para compensar a las comunidades y ciudades autónomas por los costes ocasionados por la sobreocupación por menores extranjeros no acompañados trasladados se concede un crédito extraordinario por un importe de:',
 o: ['100.000.000 de euros.', '10.000.000 de euros.', '50.000.000 de euros.', '1.000.000.000 de euros.'],
 t: 'por un importe de 100.000.000 de euros',
 p: 'Cien millones de euros.'},
{k, a: 'disp. adic. 11.ª.5', r: 'Capacidad ordinaria de los sistemas para la adecuada protección y tutela de las personas menores de edad extranjeras no acompañadas', e: 'La capacidad ordinaria de los sistemas de protección y tutela establecida en esta disposición solo podrá prorrogarse un año, mediante real decreto y previo informe de la Conferencia Sectorial. Posteriormente, se requerirá:',
 o: ['el acuerdo unánime de la Conferencia Sectorial o, en su defecto, el acuerdo por mayoría absoluta del Congreso de los Diputados.', 'el acuerdo por mayoría absoluta de la Conferencia Sectorial o, en su defecto, el acuerdo del Consejo de Ministros.', 'el acuerdo unánime de la Conferencia Sectorial o, en su defecto, el acuerdo por mayoría simple del Congreso de los Diputados.', 'el acuerdo por mayoría de dos tercios de la Conferencia Sectorial o, en su defecto, una ley de las Cortes Generales.'],
 t: 'Posteriormente, se requerirá el acuerdo unánime de la Conferencia Sectorial de Infancia y Adolescencia o, en su defecto, el acuerdo por mayoría absoluta del Congreso de los Diputados',
 p: 'Unanimidad en la Conferencia o, en su defecto, mayoría absoluta del Congreso.', d: 'dificil'},
{k, a: 'disp. adic. 12.ª', r: 'Alcance de las decisiones de la Administración General del Estado sobre la capacidad de los sistemas de protección y tutela', e: 'No podrá acordarse por la Administración General del Estado, sin el Acuerdo unánime de la Conferencia Sectorial, la reubicación obligatoria de menores extranjeros no acompañados en el territorio de aquellas comunidades y ciudades autónomas que acrediten la ocupación efectiva de un número de plazas de acogida:',
 o: ['por encima de la media del total de las plazas existentes en el conjunto del Estado por cada 100.000 habitantes.', 'superior a tres veces su capacidad ordinaria, según la certificación remitida a la Conferencia Sectorial.', 'por encima de una plaza por cada 2.500 habitantes de la comunidad o ciudad autónoma de que se trate.', 'superior al doble de la media del total de plazas existentes en el conjunto del Estado.'],
 t: 'que acrediten la ocupación efectiva de un número de plazas de acogida de personas menores de edad, ya sean extranjeras o no, por encima de la media del total de las plazas existentes en el conjunto del Estado por cada 100.000 habitantes',
 p: 'Por encima de la media estatal de plazas por cada 100.000 habitantes.', d: 'dificil'},
// pág. 48 · disposiciones transitorias, derogatoria y finales primera a tercera
{k, a: 'disp. trans. 1.ª', r: 'Regularización de extranjeros que se encuentren en España', e: 'El Gobierno, mediante Real Decreto, establecerá el procedimiento para la regularización de los extranjeros que se encuentren en territorio español antes del día:',
 o: ['1 de junio de 1999.', '1 de enero de 2000.', '11 de enero de 2000.', '1 de junio de 2000.'],
 t: 'El Gobierno, mediante Real Decreto, establecerá el procedimiento para la regularización de los extranjeros que se encuentren en territorio español antes del día 1 de junio de 1999',
 p: 'Antes del 1 de junio de 1999.', d: 'dificil'},
{k, a: 'disp. trans. 3.ª', r: 'Normativa aplicable a procedimientos en curso', e: 'Los procedimientos administrativos en curso a la entrada en vigor de la Ley Orgánica 4/2000 se tramitarán y resolverán:',
 o: ['de acuerdo con la normativa vigente en el momento de la iniciación, salvo que el interesado solicite la aplicación de la presente Ley.', 'de acuerdo con lo previsto en la presente Ley, salvo que el interesado solicite la aplicación de la normativa anterior más favorable.', 'de acuerdo con la normativa vigente en el momento de la iniciación, sin que quepa solicitar la aplicación de la nueva Ley.', 'de acuerdo con la presente Ley en todo caso, conservando validez los trámites ya realizados.'],
 t: 'Los procedimientos administrativos en curso se tramitarán y resolverán de acuerdo con la normativa vigente en el momento de la iniciación, salvo que el interesado solicite la aplicación de la presente Ley',
 p: 'En la LO 4/2000 rige la normativa del inicio (la Ley 12/2009 dispone lo contrario: se aplica la nueva salvo que se pida la anterior).', d: 'dificil'},
{k, a: 'disp. derog. única', r: 'Derogación normativa', e: 'La Ley Orgánica 4/2000 deroga:',
 o: ['la Ley Orgánica 7/1985, de 1 de julio, sobre derechos y libertades de los extranjeros en España, y cuantas disposiciones se opongan a lo establecido en esta Ley.', 'la Ley 5/1984, de 26 de marzo, reguladora del derecho de asilo y de la condición de refugiado, y cuantas disposiciones se opongan a esta Ley.', 'la Ley Orgánica 8/2000, de 22 de diciembre, de reforma de la Ley Orgánica sobre derechos y libertades de los extranjeros.', 'la Ley Orgánica 7/1985, de 1 de julio, salvo sus preceptos sobre infracciones y sanciones, que mantienen su vigencia.'],
 t: 'Queda derogada la Ley Orgánica 7/1985, de 1 de julio, sobre derechos y libertades de los extranjeros en España, y cuantas disposiciones se opongan a lo establecido en esta Ley',
 p: 'Deroga la LO 7/1985; la Ley 5/1984 la deroga la Ley 12/2009.'},
{k, a: 'disp. final 1.ª', r: 'Modificación del artículo 312 del Código Penal', e: 'Conforme a la modificación del Código Penal introducida por la Ley Orgánica 4/2000, serán castigados los que trafiquen de manera ilegal con mano de obra con las penas de:',
 o: ['prisión de dos a cinco años y multa de seis a doce meses.', 'prisión de uno a tres años y multa de doce a veinticuatro meses.', 'prisión de dos a cuatro años y multa de seis a doce meses.', 'prisión de seis meses a tres años y multa de seis a doce meses.'],
 t: 'Serán castigados con las penas de prisión de dos a cinco años y multa de seis a doce meses, los que trafiquen de manera ilegal con mano de obra',
 p: 'Prisión de dos a cinco años y multa de seis a doce meses.', d: 'dificil'},
// pág. 49 · disposiciones finales cuarta a novena
{k, a: 'disp. final 4.ª', r: 'Preceptos no orgánicos', e: 'Según la disposición sobre preceptos no orgánicos de la Ley Orgánica 4/2000, NO tienen naturaleza orgánica:',
 o: ['los preceptos sobre tasas por autorizaciones administrativas y solicitudes de visado.', 'los preceptos sobre infracciones muy graves y el régimen de sanciones pecuniarias aplicable.', 'los preceptos sobre los derechos de reunión, asociación y sindicación.', 'los preceptos sobre la expulsión del territorio y sus efectos.'],
 t: 'Los preceptos no incluidos en el apartado anterior no tienen naturaleza orgánica',
 p: 'Los artículos 44 a 49 (tasas) no figuran en la lista de preceptos orgánicos; sí los de derechos, infracciones (53 a 55) y expulsión (57 y 58).', d: 'dificil'},
{k, a: 'disp. final 5.ª bis', r: 'Código Comunitario de Visados', e: 'Las previsiones de la Ley Orgánica 4/2000 en materia de visados de tránsito y estancia se entenderán sin perjuicio de lo establecido en:',
 o: ['el Reglamento (CE) n.º 810/2009, de 13 de julio, por el que se establece un Código Comunitario sobre Visados.', 'el Convenio de aplicación del Acuerdo de Schengen, de 19 de junio de 1990, en materia de visados uniformes.', 'el Reglamento (CE) 343/2003, del Consejo, de 18 de febrero, sobre determinación del Estado responsable.', 'la Directiva 2004/38/CE relativa al derecho de los ciudadanos de la Unión a circular y residir libremente.'],
 t: 'Las previsiones de la presente Ley en materia de visados de tránsito y estancia se entenderán sin perjuicio de lo establecido en el Reglamento (CE) n.º 810/2009, de 13 de julio, por el que se establece un Código Comunitario sobre Visados',
 p: 'El Código Comunitario sobre Visados es el Reglamento (CE) 810/2009.'},
{k, a: 'disp. final 6.ª', r: 'Reglamento de la Ley', e: 'El Gobierno aprobará el Reglamento de la Ley Orgánica 4/2000 en el plazo de:',
 o: ['seis meses.', 'tres meses.', 'un año.', 'dos meses.'],
 t: 'El Gobierno en el plazo de seis meses aprobará el Reglamento de esta Ley Orgánica',
 p: 'Seis meses (también es el plazo de desarrollo reglamentario de la Ley 12/2009).'},
{k, a: 'disp. final 9.ª', r: 'Entrada en vigor', e: 'La Ley Orgánica 4/2000 entrará en vigor:',
 o: ['a los veinte días de su completa publicación en el «Boletín Oficial del Estado».', 'al día siguiente de su publicación en el «Boletín Oficial del Estado».', 'a los veinte días de su publicación, salvo sus preceptos no orgánicos.', 'al mes de su completa publicación en el «Boletín Oficial del Estado».'],
 t: 'Esta Ley Orgánica entrará en vigor a los veinte días de su completa publicación en el «Boletín Oficial del Estado»',
 p: 'A los veinte días de su completa publicación.'},
{k, a: 'disp. final 5.ª', r: 'Apoyo al sistema de información de Schengen', e: 'El Gobierno, en el marco de lo previsto en el Convenio de aplicación del Acuerdo de Schengen, adoptará cuantas medidas fueran precisas para mantener la exactitud y la actualización de los datos del sistema de información de Schengen:',
 o: ['facilitando el ejercicio del derecho a la rectificación o supresión de datos a las personas cuyos datos figuren en el mismo.', 'comunicando a los interesados, en el plazo de un mes, cualquier inclusión de sus datos en el sistema de información.', 'garantizando el acceso de las Comunidades Autónomas a los datos del sistema para el ejercicio de sus competencias.', 'remitiendo anualmente a las Cortes Generales un informe sobre el número de personas incluidas en el sistema.'],
 t: 'facilitando el ejercicio del derecho a la rectificación o supresión de datos a las personas cuyos datos figuren en el mismo',
 p: 'Se facilita el derecho de rectificación o supresión de datos.'},
// pág. 50 · Ley 12/2009, arts. 1 a 6.1
{k: l, a: 'art. 1', r: 'Objeto de la ley', e: 'La Ley 12/2009 tiene por objeto establecer los términos en que las personas nacionales de países no comunitarios y las apátridas podrán gozar en España de la protección internacional constituida por:',
 o: ['el derecho de asilo y la protección subsidiaria, así como el contenido de dicha protección internacional.', 'el derecho de asilo, la protección subsidiaria y la protección temporal en caso de afluencia masiva.', 'el estatuto de refugiado y el estatuto de apátrida, así como el contenido de dicha protección.', 'el derecho de asilo y la autorización de residencia por razones humanitarias, así como su contenido.'],
 t: 'tiene por objeto establecer los términos en que las personas nacionales de países no comunitarios y las apátridas podrán gozar en España de la protección internacional constituida por el derecho de asilo y la protección subsidiaria, así como el contenido de dicha protección internacional',
 p: 'La protección internacional la constituyen el asilo y la protección subsidiaria; la protección temporal se rige por su reglamento específico.'},
{k: l, a: 'art. 3', r: 'La condición de refugiado', e: 'La condición de refugiado se reconoce también al apátrida que, careciendo de nacionalidad y hallándose fuera del país donde antes tuviera su residencia habitual, por los mismos motivos:',
 o: ['no puede o, a causa de dichos temores, no quiere regresar a él.', 'no puede obtener la nacionalidad del país de su residencia habitual.', 'no ha podido obtener documentación de ningún Estado de forma continuada.', 'no puede regresar a él, aunque quiera hacerlo, por causas ajenas a su voluntad.'],
 t: 'o al apátrida que, careciendo de nacionalidad y hallándose fuera del país donde antes tuviera su residencia habitual, por los mismos motivos no puede o, a causa de dichos temores, no quiere regresar a él',
 p: 'Para el apátrida, la referencia es el país de su anterior residencia habitual: no puede o no quiere regresar a él.'},
{k: l, a: 'art. 5', r: 'Derechos garantizados con el asilo y la protección subsidiaria', e: 'La protección concedida con el derecho de asilo y la protección subsidiaria consiste en:',
 o: ['la no devolución ni expulsión de las personas a quienes se les haya reconocido, así como en la adopción de las medidas de efectos de la concesión previstas en la Ley.', 'la concesión de la nacionalidad española a las personas a quienes se les haya reconocido, transcurridos cinco años de residencia legal y continuada en territorio español.', 'la no devolución ni expulsión, salvo que la persona haya entrado ilegalmente en territorio español o carezca de documentación.', 'la expedición de una autorización de residencia temporal renovable cada cinco años, sin derecho a trabajar en España.'],
 t: 'La protección concedida con el derecho de asilo y la protección subsidiaria consiste en la no devolución ni expulsión de las personas a quienes se les haya reconocido',
 p: 'Consiste en la no devolución ni expulsión y en las medidas del art. 36 (efectos de la concesión).'},
{k: l, a: 'art. 6.1', r: 'Actos de persecución', e: 'Los actos en que se basen los fundados temores a ser objeto de persecución deberán ser suficientemente graves por su naturaleza o carácter reiterado como para constituir una violación grave de los derechos fundamentales, o bien:',
 o: ['ser una acumulación lo suficientemente grave de varias medidas, incluidas las violaciones de derechos humanos, como para afectar a una persona de manera similar.', 'ser una medida única de especial gravedad adoptada por agentes estatales contra una persona por motivos de raza, religión, nacionalidad u opiniones políticas.', 'ser una acumulación de varias medidas leves, aunque no afecten a la persona de manera similar a una violación grave.', 'haber sido declarados como persecución por una resolución del Alto Comisionado de las Naciones Unidas para los Refugiados.'],
 t: 'b) ser una acumulación lo suficientemente grave de varias medidas, incluidas las violaciones de derechos humanos, como para afectar a una persona de manera similar a la mencionada en la letra a)',
 p: 'La alternativa es la acumulación suficientemente grave de varias medidas.'},
{k: l, a: 'art. 7.1.d)', r: 'Motivos de persecución', e: 'El concepto de opiniones políticas comprenderá, en particular, la profesión de opiniones, ideas o creencias sobre un asunto relacionado con los agentes potenciales de persecución y con sus políticas o métodos:',
 o: ['independientemente de que el solicitante haya o no obrado de acuerdo con tales opiniones, ideas o creencias.', 'siempre que el solicitante las haya manifestado públicamente en su país de origen antes de abandonarlo.', 'siempre que el solicitante haya obrado de acuerdo con tales opiniones, ideas o creencias en su país de origen.', 'cuando el solicitante pertenezca a un partido u organización política perseguida en su país de origen.'],
 t: 'd) el concepto de opiniones políticas comprenderá, en particular, la profesión de opiniones, ideas o creencias sobre un asunto relacionado con los agentes potenciales de persecución y con sus políticas o métodos, independientemente de que el solicitante haya o no obrado de acuerdo con tales opiniones, ideas o creencias',
 p: 'Es indiferente que haya obrado o no conforme a esas opiniones.', d: 'dificil'},
// pág. 51 · Ley 12/2009, arts. 6.2 a 7
{k: l, a: 'art. 6.2', r: 'Actos de persecución', e: 'Los actos de persecución podrán revestir, entre otras, las siguientes formas: Señale la INCORRECTA.',
 o: ['denegación de la nacionalidad del Estado de residencia por razones administrativas;', 'actos de violencia física o psíquica, incluidos los actos de violencia sexual;', 'procesamientos o penas por la negativa a prestar servicio militar en un conflicto en el que el cumplimiento de dicho servicio conllevaría delitos comprendidos en las cláusulas de exclusión;', 'actos de naturaleza sexual que afecten a adultos o a niños.'],
 t: 'f) actos de naturaleza sexual que afecten a adultos o a niños',
 p: 'La denegación de la nacionalidad por razones administrativas no figura entre las formas de persecución.'},
{k: l, a: 'art. 6.3', r: 'Actos de persecución', e: 'Los actos de persecución definidos en la Ley deberán estar relacionados:',
 o: ['con los motivos de persecución mencionados en la Ley.', 'con la actuación de agentes estatales del país de origen.', 'con hechos ocurridos en los cinco años anteriores a la solicitud.', 'con la situación general de violencia en el país de origen.'],
 t: 'Los actos de persecución definidos en el presente artículo deberán estar relacionados con los motivos mencionados en el artículo siguiente',
 p: 'Deben estar relacionados con los motivos de persecución.'},
{k: l, a: 'art. 7.1.a)', r: 'Motivos de persecución', e: 'Al valorar los motivos de persecución, el concepto de raza comprenderá, en particular:',
 o: ['el color, el origen o la pertenencia a un determinado grupo étnico.', 'el color, la lengua o la pertenencia a una determinada nacionalidad.', 'el origen geográfico, la cultura o la pertenencia a un grupo social.', 'el color, el origen o las prácticas religiosas del grupo de pertenencia.'],
 t: 'a) el concepto de raza comprenderá, en particular, el color, el origen o la pertenencia a un determinado grupo étnico',
 p: 'Raza: color, origen o pertenencia a un determinado grupo étnico.'},
{k: l, a: 'art. 7.1.b)', r: 'Motivos de persecución', e: 'El concepto de religión comprenderá, en particular, la profesión de creencias:',
 o: ['teístas, no teístas y ateas, la participación o la abstención de hacerlo, en cultos formales en privado o en público.', 'teístas reconocidas oficialmente, y la participación en cultos formales en público, ya sea individualmente o en comunidad.', 'religiosas inscritas en el Registro de Entidades Religiosas, y la participación en cultos formales en privado o en público.', 'teístas y no teístas, con exclusión de las ateas, y la participación en cultos formales en privado o en público.'],
 t: 'b) el concepto de religión comprenderá, en particular, la profesión de creencias teístas, no teístas y ateas, la participación o la abstención de hacerlo, en cultos formales en privado o en público',
 p: 'Incluye creencias teístas, no teístas y ateas, y también la abstención.', d: 'dificil'},
{k: l, a: 'art. 7.1.c)', r: 'Motivos de persecución', e: 'El concepto de nacionalidad no se limitará a poseer o no la ciudadanía, sino que comprenderá, en particular:',
 o: ['la pertenencia a un grupo determinado por su identidad cultural, étnica o lingüística, sus orígenes geográficos o políticos comunes o su relación con la población de otro Estado.', 'la pertenencia a un grupo determinado por sus creencias religiosas, sus opiniones políticas o su relación con los agentes de persecución del Estado del que sea nacional el solicitante.', 'la residencia habitual en un determinado territorio, aunque se carezca de la ciudadanía de ningún Estado reconocido.', 'la pertenencia a una minoría nacional reconocida por los tratados internacionales en los que sea parte España.'],
 t: 'c) el concepto de nacionalidad no se limitará a poseer o no la ciudadanía, sino que comprenderá, en particular, la pertenencia a un grupo determinado por su identidad cultural, étnica o lingüística, sus orígenes geográficos o políticos comunes o su relación con la población de otro Estado',
 p: 'Nacionalidad: identidad cultural, étnica o lingüística, orígenes geográficos o políticos comunes o relación con la población de otro Estado.'},
{k: l, a: 'art. 7.2', r: 'Motivos de persecución', e: 'En la valoración acerca de si la persona solicitante tiene fundados temores a ser perseguida será indiferente el hecho de que posea realmente la característica racial, religiosa, nacional, social o política que suscita la persecución:',
 o: ['a condición de que el agente de persecución se la atribuya.', 'siempre que la persona solicitante la invoque expresamente.', 'a condición de que la persecución proceda del Estado.', 'siempre que se acredite mediante prueba documental.'],
 t: 'será indiferente el hecho de que posea realmente la característica racial, religiosa, nacional, social o política que suscita la persecución, a condición de que el agente de persecución se la atribuya',
 p: 'Basta con que el agente de persecución se la atribuya.'},
{k: l, a: 'art. 7.1.e)', r: 'Motivos de persecución', e: 'En función de las circunstancias imperantes en el país de origen, se incluye en el concepto de grupo social determinado un grupo basado en una característica común de orientación sexual o identidad sexual, y, o, edad. No obstante:',
 o: ['en ningún caso podrá entenderse como orientación sexual la realización de conductas tipificadas como delito en el ordenamiento jurídico español.', 'estos aspectos por sí solos darán lugar en todo caso a la aplicación del concepto de grupo social determinado, con independencia de las circunstancias del país de origen.', 'la orientación sexual solo podrá alegarse si la persona solicitante lo acredita mediante informe pericial.', 'la edad solo será tenida en cuenta cuando la persona solicitante sea menor de dieciocho años.'],
 t: 'En ningún caso podrá entenderse como orientación sexual, la realización de conductas tipificadas como delito en el ordenamiento jurídico español',
 p: 'Estos aspectos por sí solos no bastan, y en ningún caso se entienden como orientación sexual conductas delictivas.', d: 'dificil'},
];
